contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, bool freezeSender, bool freezeRecipient, uint256 value) public {
        require(to != address(0));

        c.freezeAccount(address(this), freezeSender); if (__ESBMC_reverted()) return;
        c.freezeAccount(to, freezeRecipient); if (__ESBMC_reverted()) return;

        uint256 beforeSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeRecipient = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 afterSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterRecipient = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? (afterSender == beforeSender && afterRecipient == beforeRecipient && afterSupply == beforeSupply)
                : (beforeSender >= value && afterSender == beforeSender - value && afterRecipient == beforeRecipient + value && afterSupply == beforeSupply)
        );
    }
}

